import java.util.*;
import java.lang.*;
import java.io.*;

class Codechef
{
	public static void main (String[] args) throws java.lang.Exception
	{
		// your code goes here
        Scanner sc=new Scanner(System.in);
        int t=sc.nextInt();
        while(t-->0){
            int n=sc.nextInt();
            int m=3*n;
            long[] arr=new long[m];
            for(int i=0;i<m;i++){
                arr[i]=sc.nextLong();
            }
            Arrays.sort(arr);
            long[] px=new long[m+1];
            for(int i=0;i<m;i++){
                px[i+1]=px[i]+arr[m-i-1];
            }
            long res=0;
            for(int j=0;j<=n;j++){
                int l=0;
                int h=n-j;
                
                while(l<h){
                        int b=(l+h)/2;
                        int q=j+(2*b);
                        int r=3*n-2*j-b;
                        long g=(px[q+2]-px[q])-3L*arr[m-r];
                        if(g>0){
                            l=b+1;
                        }
                        else{
                            h=b;
                        }
                }
                int b=l;
                int c=n-j-b;
                int q=j+2*b;
                int r=q+3*c;
                long curr=0;
                curr+=6L*px[j];
                curr+=4L*(px[q]-px[j]);
                curr+=3L*(px[r]-px[q]);
                res=Math.max(res,curr);
            }
            System.out.println(res);
        }
	}
}
